{
  "hypotheses": [
    {
      "text": "Data‑artifact: Tesla’s XBRL filings before FY2011 did not use the us‑gaap 'Revenues' or 'RevenueFromContractWithCustomerExcludingAssessedTax' concepts, so no revenue facts appear in the revenue_facts table for those years.",
      "how_to_test": "SELECT fiscal_year, COUNT(*) AS fact_count FROM edgar.revenue_facts WHERE cik = 1318605 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax') GROUP BY fiscal_year ORDER BY fiscal_year; -- Expect zero rows for fiscal_year < 2011."
    },
    {
      "text": "Real‑world: Tesla had negligible or zero reportable revenue before FY2011 (e.g., pre‑Model S limited Roadster sales), so the XBRL tags were present but the value_usd was zero or omitted, making the revenue history appear to start later when non‑zero values appear.",
      "how_to_test": "SELECT fiscal_year, SUM(value_usd) AS total_revenue FROM edgar.revenue_facts WHERE cik = 1318605 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax') GROUP BY fiscal_year ORDER BY fiscal_year; -- Look for years with total_revenue = 0 or NULL before 2011."
    },
    {
      "text": "Data‑artifact: Early Tesla filings (pre‑FY2011) were submitted as amendments (10‑K/A, 10‑Q/A) that created duplicate period_frame = null rows; the current revenue_facts view may have been filtered to keep only rows with a non‑null period_frame, thus dropping those early facts.",
      "how_to_test": "SELECT fiscal_year, period_frame, COUNT(*) AS rows FROM edgar.revenue_facts WHERE cik = 1318605 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax') GROUP BY fiscal_year, period_frame ORDER BY fiscal_year, period_frame; -- Check if pre‑2011 years have only period_frame IS NULL rows."
    },
    {
      "text": "Real‑world: Tesla changed its reporting status to a larger accelerated filer in FY2011 (post‑IPO), triggering mandatory XBRL tagging of the standard revenue concepts; prior to that, as a smaller reporting company, it used custom tags or omitted the standard revenue XBRL elements.",
      "how_to_test": "SELECT fiscal_year, form_type, COUNT(*) AS filings FROM edgar.revenue_facts WHERE cik = 1318605 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax') GROUP BY fiscal_year, form_type ORDER BY fiscal_year; -- Verify shift in form_type mix (e.g., more 10‑K/10‑Q vs 10‑KSB) starting FY2011."
    }
  ]
}
